templates.body:
{
  "name": "{{project.name}}",
  "fps": {{project.fps}},
  "bones": [
{{#each skeleton.bones}}    {"name":"{{name}}","parent":"{{parent}}","x":{{round x 3}},"y":{{round y 3}},"rotation":{{round rotation 3}},"length":{{round length 3}}}{{#unless @last}},{{/unless}}
{{/each}}  ],
  "slots": [
{{#each skeleton.slots}}    {"name":"{{name}}","bone":"{{bone}}","attachment":{{#if attachment}}"{{attachment}}"{{else}}null{{/if}}}{{#unless @last}},{{/unless}}
{{/each}}  ],
  "animations": [
{{#each animations}}    {"name":"{{name}}","duration":{{round duration 3}},"looping":{{looping}}}{{#unless @last}},{{/unless}}
{{/each}}  ],
  "regions": [
{{#if atlas}}{{#each atlas.regions}}    {"name":"{{name}}","page":{{page}},"x":{{x}},"y":{{y}},"w":{{width}},"h":{{height}},"offsetX":{{offset_x}},"offsetY":{{offset_y}},"originalW":{{original_width}},"originalH":{{original_height}}}{{#unless @last}},{{/unless}}
{{/each}}{{/if}}  ]
}
